import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Component;

@Component
public class EventBus {
    private final ApplicationEventPublisher publisher;

    public EventBus(ApplicationEventPublisher publisher) {
        this.publisher = publisher;
    }

    public void publish(Object event) {
        publisher.publishEvent(event);
    }
}

package com.industrial.saas.sharedkernel.domain;

import org.springframework.stereotype.Component;

@Component
public class RuleEngine {
    public boolean evaluateMachineSafetyShutdown(Float sensorValue, Float criticalThreshold) {
        return sensorValue > criticalThreshold;
    }

    public boolean evaluateMaintenanceThreshold(Float wearPercentage, Float threshold) {
        return wearPercentage >= threshold;
    }

    public boolean evaluateProductionPriority(String priority1, String priority2) {
        // HIGH > MEDIUM > LOW
        var priorityOrder = java.util.Map.of(
            "HIGH", 3,
            "MEDIUM", 2,
            "LOW", 1
        );
        return priorityOrder.getOrDefault(priority1, 0) > priorityOrder.getOrDefault(priority2, 0);
    }
}

