package com.industrial.saas.core.domain.entities;

import com.industrial.saas.core.domain.enums.FactoryStatus;
import com.industrial.saas.core.domain.valueobjects.Address;
import jakarta.persistence.*;
import lombok.Getter;
import lombok.Setter;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

@Entity
@Table(name = "factories")
@Getter
@Setter
public class Factory {
    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID factoryId;

    private String name;

    @Embedded
    private Address location;

    @Enumerated(EnumType.STRING)
    private FactoryStatus status;

    @OneToMany(mappedBy = "factory", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Machine> machines = new ArrayList<>();

    @OneToMany(mappedBy = "factory", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<ProductionOrder> productionOrders = new ArrayList<>();

    public void addMachine(Machine machine) {
        machines.add(machine);
        machine.setFactory(this);
    }

    public void addProductionOrder(ProductionOrder order) {
        productionOrders.add(order);
        order.setFactory(this);
    }
}

