package com.industrial.saas.core.domain.aggregates;

import com.industrial.saas.core.domain.entities.Factory;
import com.industrial.saas.core.domain.entities.Machine;
import com.industrial.saas.core.domain.entities.ProductionOrder;
import com.industrial.saas.core.domain.events.MachineStarted;
import com.industrial.saas.core.domain.events.ProductionOrderCompleted;
import com.industrial.saas.sharedkernel.domain.EventBus;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;
import java.time.LocalDateTime;
import java.util.UUID;

@Component
public class FactoryAggregate {
    private final EventBus eventBus;

    public FactoryAggregate(EventBus eventBus) {
        this.eventBus = eventBus;
    }

    @Transactional
    public Machine addMachineToFactory(Factory factory, String serialNumber, String model) {
        Machine machine = new Machine();
        machine.setSerialNumber(serialNumber);
        machine.setModel(model);
        machine.setInstallationDate(LocalDateTime.now());
        machine.setOperationalStatus(com.industrial.saas.core.domain.enums.MachineStatus.IDLE);

        factory.addMachine(machine);
        return machine;
    }

    @Transactional
    public ProductionOrder createProductionOrder(Factory factory, String productCode, 
                                                 Integer quantity, com.industrial.saas.core.domain.enums.OrderPriority priority) {
        ProductionOrder order = new ProductionOrder();
        order.setProductCode(productCode);
        order.setQuantity(quantity);
        order.setPriority(priority);
        order.setStatus(com.industrial.saas.core.domain.enums.OrderStatus.SCHEDULED);

        factory.addProductionOrder(order);
        return order;
    }

    public void startMachine(UUID machineId, UUID operatorId) {
        MachineStarted event = new MachineStarted(machineId, LocalDateTime.now(), operatorId);
        eventBus.publish(event);
    }

    public void completeProductionOrder(UUID orderId, Integer totalProduced) {
        ProductionOrderCompleted event = new ProductionOrderCompleted(orderId, LocalDateTime.now(), totalProduced);
        eventBus.publish(event);
    }
}

